protected BigDecimal getDefaultSupplierMinQty(Product product) {
  Partner defaultSupplierPartner = product.getDefaultSupplierPartner();
  if (appPurchaseService.getAppPurchase().getManageSupplierCatalog()) {
    List<SupplierCatalog> supplierCatalogList = product.getSupplierCatalogList();
    if (defaultSupplierPartner != null && supplierCatalogList != null) {
      for (SupplierCatalog supplierCatalog : supplierCatalogList) {
        if (supplierCatalog.getSupplierPartner().equals(defaultSupplierPartner)) {
          return supplierCatalog.getMinQty();
        }
      }
    }
  }
  return BigDecimal.ZERO;
}

def validate_parent_warehouse(self):
	warehouse = frappe.get_cached_value(
		"Warehouse", self.parent_warehouse, ["is_group", "company"], as_dict=True
	)
	if warehouse and (not warehouse.is_group or warehouse.company != self.company):
		frappe.throw(
			_("Parent Warehouse {0} must be a group warehouse of company {1}").format(
				frappe.bold(self.parent_warehouse), frappe.bold(self.company)
			)
		)

def validate_periods_and_dates(self):
	if cint(self.demand_number) <= 0:
		frappe.throw(_("Number of periods must be greater than zero"))

	for row in self.items:
		if row.delivery_date and getdate(row.delivery_date) < getdate(self.from_date):
			frappe.throw(
				_("Row #{0}: Delivery Date {1} cannot be before From Date {2}").format(
					row.idx, formatdate(row.delivery_date), formatdate(self.from_date)
				)
			)

def validate_stock_items(self):
	item_codes = {row.item_code for row in self.items + self.selected_items if row.item_code}
	if not item_codes:
		return

	non_stock_items = frappe.get_all(
		"Item", filters={"name": ["in", list(item_codes)], "is_stock_item": 0}, pluck="name"
	)
	if non_stock_items:
		frappe.throw(
			_("Only stock items can be forecast: {0}").format(
				", ".join(frappe.bold(item) for item in non_stock_items)
			)
		)

def validate_demand_qty(self):
	for row in self.items:
		if row.get("demand_qty") in (None, ""):
			frappe.throw(_("Row #{0}: Demand Qty is mandatory").format(row.idx), frappe.MandatoryError)

def generate_manual_demand(self):
	if not self.selected_items:
		return

	item_details_by_code = {
		item.name: item
		for item in frappe.get_all(
			"Item",
			filters={"name": ["in", [row.item_code for row in self.selected_items]]},
			fields=["name", "item_name", "stock_uom as uom"],
		)
	}
	ascii_items_by_lowercase_code = {}
	if frappe.db.db_type == "mariadb":
		# Unicode casefold does not always match MariaDB's collation.
		ascii_items_by_lowercase_code = {
			code.lower(): item for code, item in item_details_by_code.items() if code.isascii()
		}

	forecast_demand = []
	for row in self.selected_items:
		if row.item_code not in item_details_by_code:
			matching_item = None
			if row.item_code.isascii():
				matching_item = ascii_items_by_lowercase_code.get(row.item_code.lower())

			# Fall back to the database for other collation-equivalent Item codes.
			item_details_by_code[row.item_code] = matching_item or frappe.db.get_value(
				"Item", row.item_code, ["item_name", "stock_uom as uom"], as_dict=True
			)
		item_details = item_details_by_code[row.item_code]

		for index in range(self.demand_number):
			if self.frequency == "Monthly":
				delivery_date = add_to_date(self.from_date, months=index)
			else:
				delivery_date = add_to_date(self.from_date, weeks=index)

			forecast_demand.append(
				{
					"item_code": row.item_code,
					"delivery_date": delivery_date,
					"item_name": item_details.item_name,
					"uom": item_details.uom,
					"demand_qty": 1.0,
				}
			)

	for demand in forecast_demand:
		self.append("items", demand)

def generate_demand(self):
	self.set("items", [])
	self.generate_manual_demand()

def update_sales_forecast_status(sales_forecast):
	if not sales_forecast or frappe.db.get_value("Sales Forecast", sales_forecast, "docstatus") != 1:
		return

	status = (
		"MPS Generated"
		if frappe.db.exists("Master Production Schedule", {"sales_forecast": sales_forecast})
		else "Planned"
	)
	frappe.db.set_value("Sales Forecast", sales_forecast, "status", status)

def onload(self):
	self.set_onload(
		"enable_stock_reservation",
		frappe.db.get_single_value("Stock Settings", "enable_stock_reservation"),
	)

	if self.docstatus == 1:
		self.set_onload(
			"pending_work_order_qty",
			ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self),
		)

def validate_raw_material_group_warehouse(self):
	if not self.raw_material_group_warehouse:
		return

	group = frappe.db.get_value(
		"Warehouse",
		{"name": self.raw_material_group_warehouse, "is_group": 1, "company": self.company},
		["lft", "rgt"],
		as_dict=True,
	)
	if not group:
		frappe.throw(
			_("{0} must be a group warehouse of company {1}.").format(
				frappe.bold(_("Raw Material Group Warehouse")), frappe.bold(self.company)
			)
		)

	if self.for_warehouse and not frappe.db.exists(
		"Warehouse",
		{"name": self.for_warehouse, "is_group": 0, "lft": (">", group.lft), "rgt": ("<", group.rgt)},
	):
		frappe.throw(
			_("For Warehouse {0} must be a non-group warehouse under {1}.").format(
				frappe.bold(self.for_warehouse), frappe.bold(self.raw_material_group_warehouse)
			)
		)

def enable_auto_reserve_stock(self):
	if self.is_new() and frappe.db.get_single_value("Stock Settings", "auto_reserve_stock"):
		self.reserve_stock = 1

def validate_material_request_type(self):
	for row in self.get("mr_items"):
		if row.from_warehouse and row.material_request_type != "Material Transfer":
			row.from_warehouse = ""

def validate_sales_orders(self, sales_order=None):
	sales_orders = []

	if sales_order:
		sales_orders.append(sales_order)
	else:
		sales_orders = [row.sales_order for row in self.sales_orders if row.sales_order]

	data = sales_order_query(filters={"company": self.company, "sales_orders": sales_orders})

	title = _("Production Plan Already Submitted")
	if not data and sales_orders:
		msg = _("No items are available in the sales order {0} for production").format(sales_orders[0])
		if len(sales_orders) > 1:
			sales_orders = ", ".join(sales_orders)
			msg = _("No items are available in sales orders {0} for production").format(sales_orders)

		frappe.throw(msg, title=title)

	data = [d[0] for d in data]

	for sales_order in sales_orders:
		if sales_order not in data:
			frappe.throw(
				_("No items are available in the sales order {0} for production").format(sales_order),
				title=title,
			)

def set_pending_qty_in_row_without_reference(self):
	"Set Pending Qty in independent rows (not from SO or MR)."
	if self.docstatus > 0:  # set only to initialise value before submit
		return

	for item in self.po_items:
		if not item.get("sales_order") or not item.get("material_request"):
			item.pending_qty = item.planned_qty

def calculate_total_planned_qty(self):
	self.total_planned_qty = 0
	for d in self.po_items:
		self.total_planned_qty += flt(d.planned_qty)

def validate_data(self):
	validated_boms = set()
	for d in self.get("po_items"):
		if not d.bom_no:
			frappe.throw(_("Please select BOM for Item in Row {0}").format(d.idx))
		elif (d.item_code, d.bom_no) not in validated_boms:
			validate_bom_no(d.item_code, d.bom_no)
			validated_boms.add((d.item_code, d.bom_no))

		if not flt(d.planned_qty):
			frappe.throw(
				_("Row #{0}: Planned Qty must be greater than 0 for Item {1}.").format(
					d.idx, frappe.bold(d.item_code)
				)
			)

def _rename_temporary_references(self):
	"""po_items and sub_assembly_items items are both constructed client side without saving.

	Attempt to fix linkages by using temporary names to map final row names.
	"""
	new_name_map = {d.temporary_name: d.name for d in self.po_items if d.temporary_name}
	actual_names = {d.name for d in self.po_items}

	for sub_assy in self.sub_assembly_items:
		if sub_assy.production_plan_item not in actual_names:
			sub_assy.production_plan_item = new_name_map.get(sub_assy.production_plan_item)

def get_open_sales_orders(self):
	"""Pull sales orders  which are pending to deliver based on criteria selected"""
	open_so = get_sales_orders(self)

	if open_so:
		self.add_so_in_table(open_so)
	else:
		frappe.msgprint(_("Sales orders are not available for production"))

def add_so_in_table(self, open_so):
	"""Add sales orders in the table"""
	self.set("sales_orders", [])

	for data in open_so:
		self.append(
			"sales_orders",
			{
				"sales_order": data.name,
				"sales_order_date": data.transaction_date,
				"customer": data.customer,
				"grand_total": data.base_grand_total,
			},
		)

def add_mr_in_table(self, pending_mr):
	"""Add Material Requests in the table"""
	self.set("material_requests", [])

	for data in pending_mr:
		self.append(
			"material_requests",
			{"material_request": data.name, "material_request_date": data.transaction_date},
		)

def combine_so_items(self):
	if self.combine_items and self.po_items and len(self.po_items) > 0:
		items = []
		for row in self.po_items:
			items.append(
				frappe._dict(
					{
						"parent": row.sales_order,
						"item_code": row.item_code,
						"warehouse": row.warehouse,
						"qty": row.pending_qty,
						"pending_qty": row.pending_qty,
						"conversion_factor": 1.0,
						"description": row.description,
						"bom_no": row.bom_no,
					}
				)
			)

		self.set("po_items", [])
		self.add_items(items)
	else:
		self.get_items()

def get_items(self):
	self.set("po_items", [])
	if self.get_items_from == "Sales Order":
		self.get_so_items()

	elif self.get_items_from == "Material Request":
		self.get_mr_items()

def add_items(self, items):
	refs = {}
	for data in items:
		if not data.pending_qty:
			continue

		item_details = get_item_details(data.item_code, throw=False)
		if self.combine_items:
			bom_no = item_details.get("bom_no")
			if data.get("bom_no"):
				bom_no = data.get("bom_no")

			if bom_no in refs:
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)
				refs[bom_no]["qty"] += data.pending_qty
				continue

			else:
				refs[bom_no] = {
					"qty": data.pending_qty,
					"po_item_ref": data.name,
					"so_details": [],
				}
				refs[bom_no]["so_details"].append(
					{"sales_order": data.parent, "sales_order_item": data.name, "qty": data.pending_qty}
				)

		bom_no = data.bom_no or item_details and item_details.get("bom_no") or ""
		if not bom_no:
			continue

		pi = self.append(
			"po_items",
			{
				"warehouse": data.warehouse,
				"item_code": data.item_code,
				"description": data.description or item_details.description,
				"stock_uom": item_details and item_details.stock_uom or "",
				"bom_no": bom_no,
				"planned_qty": data.pending_qty,
				"pending_qty": data.pending_qty,
				"planned_start_date": now_datetime(),
				"product_bundle_item": data.parent_item,
			},
		)
		pi._set_defaults()

		if self.get_items_from == "Sales Order":
			pi.sales_order = data.parent
			pi.sales_order_item = data.name
			pi.description = data.description

		elif self.get_items_from == "Material Request":
			pi.material_request = data.parent
			pi.material_request_item = data.name
			pi.description = data.description

	if refs:
		for po_item in self.po_items:
			po_item.planned_qty = refs[po_item.bom_no]["qty"]
			po_item.pending_qty = refs[po_item.bom_no]["qty"]
			po_item.sales_order = ""
		self.add_pp_ref(refs)

def add_pp_ref(self, refs):
	for bom_no in refs:
		for so_detail in refs[bom_no]["so_details"]:
			self.append(
				"prod_plan_references",
				{
					"item_reference": refs[bom_no]["po_item_ref"],
					"sales_order": so_detail["sales_order"],
					"sales_order_item": so_detail["sales_order_item"],
					"qty": so_detail["qty"],
				},
			)

def calculate_total_produced_qty(self):
	self.total_produced_qty = 0
	for d in self.po_items:
		self.total_produced_qty += flt(d.produced_qty)

	self.db_set("total_produced_qty", self.total_produced_qty, update_modified=False)

def update_produced_pending_qty(self, produced_qty, production_plan_item):
	for data in self.po_items:
		if data.name == production_plan_item:
			data.produced_qty = produced_qty
			data.pending_qty = flt(data.planned_qty - produced_qty)
			data.db_update()

	self.calculate_total_produced_qty()
	self.update_status_and_bin_qty()

def update_status_and_bin_qty(self):
	previous_status = self.status
	self.set_status()
	self.db_set("status", self.status)
	if previous_status != self.status and "Completed" in (previous_status, self.status):
		self.update_bin_qty()

def validate_sales_order_planned_qty(self):
	planned_qty = self.get_so_item_planned_qty()
	if not planned_qty:
		return

	already_planned = self.get_so_wise_planned_qty(list({key[0] for key in planned_qty}))
	so_items = {
		row.name: row
		for row in frappe.get_all(
			"Sales Order Item",
			filters={"name": ("in", [key[1] for key in planned_qty])},
			fields=["name", "item_code", "stock_qty", "stock_uom"],
		)
	}
	allowance = flt(
		frappe.db.get_single_value("Manufacturing Settings", "overproduction_percentage_for_sales_order")
	)
	precision = frappe.get_precision("Production Plan Item", "planned_qty")

	for (sales_order, so_item), qty in planned_qty.items():
		row = so_items[so_item]
		unplanned_qty = flt(
			flt(row.stock_qty) * (1 + allowance / 100) - flt(already_planned.get((sales_order, so_item))),
			precision,
		)
		if flt(qty, precision) > unplanned_qty:
			frappe.throw(
				_(
					"Cannot plan {0} {1} of Item {2} against Sales Order {3}. Only {4} {1} is left to plan."
				).format(
					qty, row.stock_uom, frappe.bold(row.item_code), sales_order, max(unplanned_qty, 0)
				),
				title=_("Sales Order Qty Exceeded"),
			)

def get_so_item_planned_qty(self):
	"""Planned qty per Sales Order line, excluding product bundle components."""
	planned_qty = {}
	for row in self.po_items:
		if row.sales_order and row.sales_order_item and not row.product_bundle_item:
			key = (row.sales_order, row.sales_order_item)
			planned_qty[key] = planned_qty.get(key, 0) + flt(row.planned_qty)

	return planned_qty

def update_stock_reservation(self):
	if not self.reserve_stock:
		return

	reserve_stock_for_production_plan(self)

def add_reference_to_raw_materials(self):
	for item in self.mr_items:
		if reference := next(
			(
				sa_item.name
				for sa_item in self.sub_assembly_items
				if sa_item.production_item == item.main_item_code and sa_item.bom_no == item.from_bom
			),
			None,
		):
			item.db_set("sub_assembly_item_reference", reference)
		elif (
			self.reserve_stock
			and item.main_item_code
			and item.from_bom
			and item.main_item_code != frappe.get_cached_value("BOM", item.from_bom, "item")
		):
			frappe.throw(
				_(
					"Sub assembly item references are missing. Please fetch the sub assemblies and raw materials again."
				)
			)

def update_sales_order(self):
	so_items = {
		(row.sales_order, row.sales_order_item)
		for row in self.po_items + self.prod_plan_references
		if row.sales_order and row.sales_order_item
	}
	if not so_items:
		return

	so_wise_planned_qty = self.get_so_wise_planned_qty(list({key[0] for key in so_items}))
	for key in so_items:
		frappe.db.set_value(
			"Sales Order Item", key[1], "production_plan_qty", flt(so_wise_planned_qty.get(key))
		)

def update_bin_qty(self, item_codes: set[str] | None = None):
	rows = [(d.item_code, d.warehouse) for d in self.mr_items]
	rows += [
		(d.production_item, d.fg_warehouse)
		for d in self.sub_assembly_items
		if d.type_of_manufacturing == "In House"
	]
	for item_code, warehouse in rows:
		if warehouse and (item_codes is None or item_code in item_codes):
			bin_name = get_or_make_bin(item_code, warehouse)
			bin = frappe.get_doc("Bin", bin_name, for_update=True)
			bin.update_reserved_qty_for_production_plan()

def delete_draft_work_order(self):
	for d in frappe.get_all(
		"Work Order", fields=["name"], filters={"docstatus": 0, "production_plan": ("=", self.name)}
	):
		frappe.delete_doc("Work Order", d.name)

def cancel_untouched_stock_reservations(self):
	sre_list = frappe.get_all(
		"Stock Reservation Entry",
		filters={
			"voucher_type": self.doctype,
			"voucher_no": self.name,
			"docstatus": 1,
			"status": ("in", ["Reserved", "Partially Reserved"]),
		},
		pluck="name",
	)
	for sre_name in sre_list:
		sre_doc = frappe.get_doc("Stock Reservation Entry", sre_name)
		sre_doc.flags.ignore_permissions = True
		sre_doc.cancel()

def set_status(self, close: bool | None = None, update_bin: bool = False):
	self.check_permission("write")

	if close is None and self.status == "Closed":
		return

	self.status = {0: "Draft", 1: "Submitted", 2: "Cancelled"}.get(self.docstatus)

	if close:
		self.db_set("status", "Closed")
		self.cancel_untouched_stock_reservations()
		self.update_bin_qty()
		return

	if self.total_produced_qty > 0:
		self.status = "In Process"
		if self.all_items_completed():
			self.status = "Completed"

	if self.status != "Completed":
		self.update_requested_status()
		self.update_ordered_status()

	if close is not None:
		self.db_set("status", self.status)

	if update_bin and self.docstatus == 1 and self.status != "Completed":
		self.update_bin_qty()

def update_ordered_status(self):
	for child_table in ["po_items", "sub_assembly_items"]:
		for item in self.get(child_table):
			if item.ordered_qty:
				self.status = "In Process"
				return

def update_requested_status(self):
	if self.mr_items and all(flt(d.requested_qty) >= flt(d.quantity) for d in self.mr_items):
		self.status = "Material Requested"

def validate_plan_is_open(self):
	status = (
		frappe.db.get_value("Production Plan", self.name, "status") if not self.is_new() else self.status
	)
	if status in ("Closed", "Completed"):
		frappe.throw(
			_("Production Plan {0} is {1}").format(frappe.bold(self.name), _(status)),
			frappe.InvalidStatusError,
		)

def make_work_order_for_finished_goods(self, wo_list, default_warehouses):
	items_data = self.get_production_items()

	for _key, item in items_data.items():
		if self.sub_assembly_items:
			item["use_multi_level_bom"] = 0

		set_default_warehouses(item, default_warehouses)
		work_order = self.create_work_order(item)
		if work_order:
			wo_list.append(work_order)

def make_work_order_for_subassembly_items(self, wo_list, subcontracted_po, default_warehouses):
	pending = ProductionPlanWorkOrderQuantities(self.name).get_pending_quantities(self)
	for row in self.sub_assembly_items:
		if row.type_of_manufacturing == "Subcontract":
			subcontracted_po.setdefault(row.supplier, []).append(row)
			continue

		if row.type_of_manufacturing == "Material Request":
			continue

		work_order_data = {
			"source_warehouse": frappe.get_value("BOM", row.bom_no, "default_source_warehouse"),
			"wip_warehouse": default_warehouses.get("wip_warehouse"),
			"fg_warehouse": default_warehouses.get("fg_warehouse"),
			"scrap_warehouse": default_warehouses.get("scrap_warehouse"),
			"company": self.get("company"),
		}

		self.prepare_data_for_sub_assembly_items(
			row, work_order_data, pending["production_plan_sub_assembly_item"][row.name]
		)

		if work_order_data.get("qty") <= 0:
			continue

		work_order = self.create_work_order(work_order_data)
		if work_order:
			wo_list.append(work_order)

def get_subcontracted_qty(self):
	po_item = frappe.qb.DocType("Purchase Order Item")
	return frappe._dict(
		(
			frappe.qb.from_(po_item)
			.select(po_item.production_plan_sub_assembly_item, Sum(po_item.fg_item_qty))
			.where((po_item.production_plan == self.name) & (po_item.docstatus < 2))
			.groupby(po_item.production_plan_sub_assembly_item)
		).run()
	)

def show_list_created_message(self, doctype, doc_list=None):
	if not doc_list:
		return

	frappe.flags.mute_messages = False
	msgprint(_("{0} created").format(get_filtered_list_link(doctype, doc_list)))

def validate_mr_subcontracted(self):
	for row in self.mr_items:
		if row.material_request_type == "Subcontracting":
			if not frappe.db.get_value("Item", row.item_code, "is_sub_contracted_item"):
				frappe.throw(
					_("Item {0} is not a subcontracted item").format(row.item_code),
					title=_("Invalid Item"),
				)

def make_material_request(self):
	self.load_saved_plan_for_material_request()
	self.validate_mr_subcontracted()

	"""Create Material Requests grouped by Sales Order and Material Request Type"""
	material_request_list = []
	material_request_map = {}
	draft_qty = self.get_draft_requested_qty()

	for item in self.mr_items:
		qty_to_request = get_qty_to_request(item, draft_qty)
		if qty_to_request <= 0:
			continue

		item_doc = frappe.get_cached_doc("Item", item.item_code)

		# a group warehouse cannot receive stock; it must never reach a Material Request line
		if item.warehouse and frappe.get_cached_value("Warehouse", item.warehouse, "is_group"):
			frappe.throw(
				_("Cannot create Material Request for item {0} in group warehouse {1}.").format(
					frappe.bold(item.item_code), frappe.bold(item.warehouse)
				)
			)

		material_request_type = item.material_request_type or item_doc.default_material_request_type

		# key for Sales Order:Material Request Type:Customer
		key = "{}:{}:{}".format(item.sales_order, material_request_type, "")
		schedule_date = item.schedule_date or add_days(nowdate(), cint(item_doc.lead_time_days))

		if key not in material_request_map:
			# make a new MR for the combination
			material_request_map[key] = frappe.new_doc("Material Request")
			material_request = material_request_map[key]
			material_request.update(
				{
					"transaction_date": nowdate(),
					"status": "Draft",
					"company": self.company,
					"material_request_type": material_request_type,
				}
			)
			material_request_list.append(material_request)
		else:
			material_request = material_request_map[key]

		# add item
		material_request.append(
			"items",
			{
				"item_code": item.item_code,
				"from_warehouse": item.from_warehouse
				if material_request_type == "Material Transfer"
				else None,
				"qty": qty_to_request,
				"uom": item.uom,
				"schedule_date": schedule_date,
				"warehouse": item.warehouse,
				"sales_order": item.sales_order,
				"production_plan": self.name,
				"material_request_plan_item": item.name,
				"project": frappe.db.get_value("Sales Order", item.sales_order, "project")
				if item.sales_order
				else None,
			},
		)

	if not material_request_list:
		msgprint(_("All items are already requested"))
		return

	for material_request in material_request_list:
		# submit
		material_request.flags.ignore_permissions = 1
		material_request.run_method("set_missing_values")

		material_request.save()
		if self.get("submit_material_request"):
			material_request.submit()

	frappe.flags.mute_messages = False

	if material_request_list:
		material_request_list = [
			get_link_to_form("Material Request", m.name) for m in material_request_list
		]
		msgprint(_("{0} created").format(comma_and(material_request_list)))
	else:
		msgprint(_("No material request created"))

def get_draft_requested_qty(self):
	mr_item = frappe.qb.DocType("Material Request Item")
	return frappe._dict(
		(
			frappe.qb.from_(mr_item)
			.select(mr_item.material_request_plan_item, Sum(mr_item.stock_qty))
			.where((mr_item.production_plan == self.name) & (mr_item.docstatus == 0))
			.groupby(mr_item.material_request_plan_item)
		).run()
	)

def set_sub_assembly_items_based_on_level(self, row, bom_data, manufacturing_type=None):
	"Modify bom_data, set additional details."
	is_group_warehouse = frappe.db.get_value("Warehouse", self.sub_assembly_warehouse, "is_group")

	for data in bom_data:
		data.qty = data.stock_qty
		data.production_plan_item = row.name
		data.schedule_date = row.planned_start_date
		data.type_of_manufacturing = manufacturing_type or (
			"Subcontract" if data.is_sub_contracted_item else "In House"
		)

		if not is_group_warehouse:
			data.fg_warehouse = self.sub_assembly_warehouse

		if not self.combine_sub_items:
			data.sales_order = row.sales_order
			data.sales_order_item = row.sales_order_item

def all_items_completed(self):
	all_items_produced = all(flt(d.planned_qty) - flt(d.produced_qty) < 0.000001 for d in self.po_items)
	if not all_items_produced:
		return False

	wo_status = frappe.get_all(
		"Work Order",
		filters={
			"production_plan": self.name,
			"status": ("not in", ["Closed", "Stopped"]),
			"docstatus": 1,
		},
		fields="status",
		pluck="status",
	)
	all_work_orders_completed = all(s == "Completed" for s in wo_status)
	return all_work_orders_completed

def get_mr_item_planned_qty_query(mr_item):
	plan_item = frappe.qb.DocType("Production Plan Item")
	return (
		frappe.qb.from_(plan_item)
		.select(Sum(plan_item.planned_qty))
		.where((plan_item.material_request_item == mr_item.name) & (plan_item.docstatus == 1))
