def reserve_stock_for_production_plan(doc, items=None, table_name=None, notify=False):
	"""Reserve stock for a Production Plan. Internal: no permission check, because the Production
	Plan submit and cancel lifecycles reach it for a user who need not hold Production Plan write.
	The cancelled branch unreserves, so the whitelisted entry point above needs the same right as
	the cancel sibling.
	"""
	if items and isinstance(items, str):
		items = parse_json(items)

	mapper = {
		"sub_assembly_items": {
			"table_name": "sub_assembly_items",
			"qty_field": "required_qty",
			"warehouse_field": "fg_warehouse",
		},
		"mr_items": {
			"table_name": "mr_items",
			"qty_field": "required_bom_qty",
			"warehouse_field": "warehouse",
		},
	}

	for child_table_name in mapper:
		if table_name and table_name != child_table_name:
			continue

		sre = StockReservation(doc, items=items, kwargs=mapper[child_table_name], notify=notify)
		if doc.docstatus == 1:
			sre_created = sre.make_stock_reservation_entries()
			if sre_created:
				frappe.msgprint(_("Stock Reservation Entries Created"), alert=True)
		elif doc.docstatus == 2:
			sre.cancel_stock_reservation_entries()

	doc.reload()

def get_active(self, name):
    pool = Pool()
    Date = pool.get('ir.date')
    return self.to_date >= Date.today()

def search_active(cls, name, clause):
    pool = Pool()
    Date = pool.get('ir.date')

    today = Date.today()
    operators = {
        '=': '>=',
        '!=': '<',
        }
    reverse = {
        '=': '!=',
        '!=': '=',
        }
    if clause[1] in operators:
        if clause[2]:
            return [('to_date', operators[clause[1]], today)]
        else:
            return [('to_date', operators[reverse[clause[1]]], today)]
    else:
        return []

def check_modification(cls, mode, forecasts, values=None, external=False):
    super().check_modification(
        mode, forecasts, values=values, external=external)
    if mode == 'delete':
        for forecast in forecasts:
            if forecast.state not in {'cancelled', 'draft'}:
                raise AccessError(gettext(
                        'stock_forecast.msg_forecast_delete_cancel',
                        forecast=forecast.rec_name))

def create_moves(forecasts):
    'Create stock moves for the forecast ids'
    pool = Pool()
    Move = pool.get('stock.move')

    with Move.bulk_save() as save:
        for forecast in forecasts:
            if forecast.state == 'done':
                for line in forecast.lines:
                    save.extend(line.get_moves())

